<?php
require '../../includes/header.php';require '../../includes/role_guard.php';requireRole(['admin','staff','tribe_leader','tribe_rep']);require '../../includes/db.php';require_once '../../includes/real_data_normalization.php';require_once '../../includes/family_access.php';$family=require_family_access($conn,(int)($_GET['id']??0));$head=family_member($conn,(int)$family['id'],'head');$spouse=family_member($conn,(int)$family['id'],'spouse');function display_person(?array$p):string{return$p?trim(implode(' ',array_filter([$p['first_name'],$p['middle_name'],$p['last_name'],$p['suffix']]))):'Not recorded';}
$fid=(int)$family['id'];$records=$conn->query("SELECT r.id,r.reference_code,r.full_name,r.status FROM ip_records r JOIN ip_family_members m ON m.id=r.family_member_id WHERE m.family_id=$fid ORDER BY r.id")->fetch_all(MYSQLI_ASSOC);$cases=$conn->query("SELECT DISTINCT c.id,c.case_title,c.status FROM case_applications c JOIN case_persons_involved cp ON cp.case_id=c.id JOIN ip_family_members m ON m.id=cp.family_member_id WHERE m.family_id=$fid ORDER BY c.updated_at DESC")->fetch_all(MYSQLI_ASSOC);$tax=$conn->query("SELECT DISTINCT t.id,t.td_number,t.declaration_status,p.land_name FROM tax_declarations t LEFT JOIN ip_land_parcels p ON p.id=t.parcel_id WHERE t.owner_family_id=$fid OR t.owner_family_member_id IN(SELECT id FROM ip_family_members WHERE family_id=$fid) ORDER BY t.id DESC")->fetch_all(MYSQLI_ASSOC);
?><main class="main-no-right"><header class="workspace-header"><div><div class="eyebrow">IP Family Registry</div><h1><?=e(display_person($head))?></h1><p><?=e($family['family_reference'])?> · <?=e($family['affiliation_name']?:'Affiliation not recorded')?></p></div><div class="workspace-actions"><a class="btn btn-success" href="edit.php?id=<?=$fid?>"><i class="bi bi-pencil me-1"></i>Edit Family</a></div></header><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Family record saved successfully.</div><?php endif;?>
<div class="row g-3 mb-3"><div class="col-lg-6"><section class="card-box h-100"><div class="section-title">Family Members</div><dl class="row mb-0"><dt class="col-sm-4">Head</dt><dd class="col-sm-8"><?=e(display_person($head))?></dd><dt class="col-sm-4">Sex / Birthday</dt><dd class="col-sm-8"><?=e(implode(' · ',array_filter([$head['sex']??null,$head['birthdate']??null]))?:'Not recorded')?></dd><dt class="col-sm-4">Spouse</dt><dd class="col-sm-8"><?=e(display_person($spouse))?></dd><?php if($spouse):?><dt class="col-sm-4">Sex / Birthday</dt><dd class="col-sm-8"><?=e(implode(' · ',array_filter([$spouse['sex'],$spouse['birthdate']]))?:'Not recorded')?></dd><?php endif;?></dl></section></div><div class="col-lg-6"><section class="card-box h-100"><div class="section-title">Address and Contact</div><dl class="row mb-0"><?php foreach(['region'=>'Region','province'=>'Province','municipality_city'=>'Municipality / City','barangay'=>'Barangay','house_number'=>'House No.','sitio_street'=>'Sitio / Street','contact_number'=>'Contact']as$k=>$label):?><dt class="col-sm-4"><?=$label?></dt><dd class="col-sm-8"><?=e($family[$k]?:'Not recorded')?></dd><?php endforeach;?></dl></section></div></div>
<section class="card-box mb-3"><div class="section-title">Connected Records and Workflows</div><p class="small text-muted">Only explicit reviewed relationships are shown; matching is never inferred from names.</p><div class="row g-3"><div class="col-lg-4"><h6>Individual Records <span class="badge bg-light text-dark"><?=count($records)?></span></h6><?php foreach($records as$r):?><a class="d-block border-bottom py-2 text-decoration-none" href="../admin/records/view.php?id=<?=$r['id']?>"><strong><?=e($r['full_name'])?></strong><small class="d-block text-muted"><?=e($r['reference_code'])?> · <?=e(ucwords(str_replace('_',' ',$r['status'])))?></small></a><?php endforeach;?><?php if(!$records):?><span class="text-muted small">No linked individual record.</span><?php endif;?></div><div class="col-lg-4"><h6>Cases <span class="badge bg-light text-dark"><?=count($cases)?></span></h6><?php foreach($cases as$c):?><a class="d-block border-bottom py-2 text-decoration-none" href="../admin/cases/view.php?id=<?=$c['id']?>"><strong><?=e($c['case_title'])?></strong><small class="d-block text-muted"><?=e(ucwords(str_replace('_',' ',$c['status'])))?></small></a><?php endforeach;?><?php if(!$cases):?><span class="text-muted small">No case participant is linked to this family.</span><?php endif;?></div><div class="col-lg-4"><h6>Tax / Parcel Evidence <span class="badge bg-light text-dark"><?=count($tax)?></span></h6><?php foreach($tax as$t):?><a class="d-block border-bottom py-2 text-decoration-none" href="../tax_declarations/view.php?id=<?=$t['id']?>"><strong><?=e($t['td_number'])?></strong><small class="d-block text-muted"><?=e($t['land_name']?:'No mapped parcel')?> · <?=e(ucfirst($t['declaration_status']))?></small></a><?php endforeach;?><?php if(!$tax):?><span class="text-muted small">No Tax Declaration owner link.</span><?php endif;?></div></div></section>
<section class="card-box"><div class="section-title">Registry Information</div><dl class="row mb-0"><dt class="col-md-2">Affiliation</dt><dd class="col-md-4"><?=e($family['affiliation_name']?:'Not recorded')?></dd><dt class="col-md-2">Operational owner</dt><dd class="col-md-4"><?=e($family['owning_tribe'])?></dd><dt class="col-md-2">ID Type</dt><dd class="col-md-4"><?=e($family['id_type']?:'Not recorded')?></dd><dt class="col-md-2">ID Number</dt><dd class="col-md-4"><?=e($family['id_number']?:'Not recorded')?></dd><dt class="col-md-2">Remarks</dt><dd class="col-md-10"><?=nl2br(e($family['remarks']?:'Not recorded'))?></dd></dl></section></main><?php require '../../includes/footer.php';?>
